const listAllocatableComponents = `-- name: ListAllocatableComponents :many
SELECT component_id, tenant_id, unit_number, collection_id, donor_id, source, component_class, abo, rhd, status, discard_reason, volume_ml, attributes, location, collected_at, expires_at, created_at, created_by, version FROM bloodbank.component
WHERE tenant_id = $1
  AND component_class = $2
  AND status = 'available'
  AND expires_at > $3
ORDER BY expires_at
LIMIT $4
`

type ListAllocatableComponentsParams struct {
	TenantID       uuid.UUID
	ComponentClass string
	AsOf           pgtype.Timestamptz
	RowLimit       int32
}

// The allocation search. Soonest to expire first, so the bank issues the unit
// that would otherwise be wasted. Compatibility is the domain's to decide, so
// this narrows by component and status and hands back candidates.
func (q *Queries) ListAllocatableComponents(ctx context.Context, arg ListAllocatableComponentsParams) ([]BloodbankComponent, error) {
	rows, err := q.db.Query(ctx, listAllocatableComponents,
		arg.TenantID,
		arg.ComponentClass,
		arg.AsOf,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []BloodbankComponent{}
	for rows.Next() {
		var i BloodbankComponent
		if err := rows.Scan(
			&i.ComponentID,
			&i.TenantID,
			&i.UnitNumber,
			&i.CollectionID,
			&i.DonorID,
			&i.Source,
			&i.ComponentClass,
			&i.Abo,
			&i.Rhd,
			&i.Status,
			&i.DiscardReason,
			&i.VolumeMl,
			&i.Attributes,
			&i.Location,
			&i.CollectedAt,
			&i.ExpiresAt,
			&i.CreatedAt,
			&i.CreatedBy,
			&i.Version,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

