const listUnreconciledIssues = `-- name: ListUnreconciledIssues :many
SELECT issue_id, tenant_id, component_id, reservation_id, patient_id, request_id, destination, emergency, emergency_authoriser, emergency_reason, reconciled, reconciled_at, reconciled_by, reconcile_note, issued_at, issued_by, issued_to, checked_by FROM bloodbank.issue
WHERE tenant_id = $1 AND emergency AND NOT reconciled
ORDER BY issued_at
LIMIT $2
`

type ListUnreconciledIssuesParams struct {
	TenantID uuid.UUID
	RowLimit int32
}

// The outstanding reconciliation list: SRS-BLD-016's "later reconciled" is
// read against this.
func (q *Queries) ListUnreconciledIssues(ctx context.Context, arg ListUnreconciledIssuesParams) ([]BloodbankIssue, error) {
	rows, err := q.db.Query(ctx, listUnreconciledIssues, arg.TenantID, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []BloodbankIssue{}
	for rows.Next() {
		var i BloodbankIssue
		if err := rows.Scan(
			&i.IssueID,
			&i.TenantID,
			&i.ComponentID,
			&i.ReservationID,
			&i.PatientID,
			&i.RequestID,
			&i.Destination,
			&i.Emergency,
			&i.EmergencyAuthoriser,
			&i.EmergencyReason,
			&i.Reconciled,
			&i.ReconciledAt,
			&i.ReconciledBy,
			&i.ReconcileNote,
			&i.IssuedAt,
			&i.IssuedBy,
			&i.IssuedTo,
			&i.CheckedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reconcileIssue = `-- name: ReconcileIssue :execrows
UPDATE bloodbank.issue
SET reconciled = true, reconciled_at = $1,
    reconciled_by = $2, reconcile_note = $3
WHERE tenant_id = $4 AND issue_id = $5
  AND emergency AND NOT reconciled
`

type ReconcileIssueParams struct {
	ReconciledAt  pgtype.Timestamptz
	ReconciledBy  string
	ReconcileNote string
	TenantID      uuid.UUID
	IssueID       uuid.UUID
}

func (q *Queries) ReconcileIssue(ctx context.Context, arg ReconcileIssueParams) (int64, error) {
	result, err := q.db.Exec(ctx, reconcileIssue,
		arg.ReconciledAt,
		arg.ReconciledBy,
		arg.ReconcileNote,
		arg.TenantID,
		arg.IssueID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

