const upsertStockThreshold = `-- name: UpsertStockThreshold :exec
INSERT INTO bloodbank.stock_threshold (
    threshold_id, tenant_id, facility_id, component_class, abo, rhd,
    minimum, set_by, set_at
) VALUES (
    $1, $2, $3, $4, $5, $6,
    $7, $8, $9
)
ON CONFLICT (tenant_id, facility_id, component_class, abo, rhd) DO UPDATE
SET minimum = EXCLUDED.minimum,
    set_by = EXCLUDED.set_by,
    set_at = EXCLUDED.set_at
`

type UpsertStockThresholdParams struct {
	ThresholdID    uuid.UUID
	TenantID       uuid.UUID
	FacilityID     string
	ComponentClass string
	Abo            string
	Rhd            string
	Minimum        int32
	SetBy          string
	SetAt          pgtype.Timestamptz
}

func (q *Queries) UpsertStockThreshold(ctx context.Context, arg UpsertStockThresholdParams) error {
	_, err := q.db.Exec(ctx, upsertStockThreshold,
		arg.ThresholdID,
		arg.TenantID,
		arg.FacilityID,
		arg.ComponentClass,
		arg.Abo,
		arg.Rhd,
		arg.Minimum,
		arg.SetBy,
		arg.SetAt,
	)
	return err
}
